package org.springframework.samples.petclinic.rest.advice;

import java.util.Locale;
import java.util.Map;

/**
 * Canonicalises a free-text street address: trims and collapses whitespace, upper-cases,
 * and expands common abbreviations (ST -> STREET, RD -> ROAD, AVE -> AVENUE). A blank or
 * {@code null} input normalises to the empty string.
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS =
        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String cleaned = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (cleaned.isEmpty()) {
            return "";
        }
        String[] tokens = cleaned.split(" ");
        StringBuilder sb = new StringBuilder(cleaned.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}

